"""HTTP surface for DocScribe.

FastAPI when it is installed; otherwise a small stdlib fallback server exposing
the same routes, so the demo runs on a bare Python install. Both paths share the
handler functions below, which is the only way to keep them honest.
"""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any

from agent import SummarizerAgent
from config import settings
from jobqueue import JobQueue, Phase
from store import Store

store = Store(settings.db_path)
agent = SummarizerAgent(store)
queue = JobQueue(store, agent)

FRONTEND_DIR = Path(__file__).resolve().parent.parent / "frontend"


# --------------------------------------------------------------------- handlers


def handle_health() -> dict[str, Any]:
    return {
        "status": "ok",
        "docs_dir": str(settings.docs_dir),
        "worker": queue._thread is not None,
        "phases": [phase.value for phase in Phase],
    }


def handle_list_docs() -> dict[str, Any]:
    available = sorted(path.stem for path in settings.docs_dir.glob("*.md"))
    known = {doc.doc_id: doc.to_dict() for doc in store.list_documents()}
    return {
        "documents": [known.get(doc_id, {"doc_id": doc_id, "title": doc_id, "tokens": 0}) for doc_id in available]
    }


def handle_create_job(payload: dict[str, Any]) -> dict[str, Any]:
    """Queue a summarization job.

    TODO: validate the payload. `doc_id` is passed straight through to the agent.
    """
    doc_id = payload.get("doc_id")
    job_id = queue.submit(doc_id)
    return {"job_id": job_id, "doc_id": doc_id, "state": "queued"}


def handle_get_job(job_id: str) -> dict[str, Any] | None:
    return store.get_job(job_id)


def handle_list_jobs() -> dict[str, Any]:
    return {"jobs": store.list_jobs()}


def handle_reset() -> dict[str, Any]:
    store.clear_summaries()
    return {"status": "summaries cleared"}


# ----------------------------------------------------------------------- FastAPI

try:  # pragma: no cover - exercised by whichever branch the environment allows
    from fastapi import FastAPI, HTTPException
    from fastapi.responses import FileResponse
    from fastapi.staticfiles import StaticFiles

    app = FastAPI(title="DocScribe", version="0.3.0")

    @app.on_event("startup")
    def _startup() -> None:
        if settings.enable_worker:
            queue.start()

    @app.on_event("shutdown")
    def _shutdown() -> None:
        queue.stop()

    @app.get("/health")
    def health() -> dict[str, Any]:
        return handle_health()

    @app.get("/docs-list")
    def list_docs() -> dict[str, Any]:
        return handle_list_docs()

    @app.post("/jobs")
    def create_job(payload: dict) -> dict[str, Any]:
        return handle_create_job(payload)

    @app.get("/jobs")
    def list_jobs() -> dict[str, Any]:
        return handle_list_jobs()

    @app.get("/jobs/{job_id}")
    def get_job(job_id: str) -> dict[str, Any]:
        job = handle_get_job(job_id)
        if job is None:
            raise HTTPException(status_code=404, detail="unknown job")
        return job

    @app.post("/admin/reset")
    def reset() -> dict[str, Any]:
        return handle_reset()

    if FRONTEND_DIR.exists():
        app.mount("/ui", StaticFiles(directory=str(FRONTEND_DIR), html=True), name="ui")

        @app.get("/")
        def index() -> FileResponse:
            return FileResponse(str(FRONTEND_DIR / "index.html"))

    HAS_FASTAPI = True

except ImportError:  # pragma: no cover
    app = None
    HAS_FASTAPI = False


# ------------------------------------------------------------- stdlib fallback


def _build_stdlib_server(host: str, port: int):
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    from urllib.parse import urlparse

    class Handler(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"

        def _send(self, status: int, body: Any, content_type: str = "application/json") -> None:
            raw = body if isinstance(body, bytes) else json.dumps(body).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(raw)))
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(raw)

        def log_message(self, *args: Any) -> None:  # keep the console readable
            return

        def do_GET(self) -> None:
            path = urlparse(self.path).path
            if path == "/health":
                return self._send(200, handle_health())
            if path == "/docs-list":
                return self._send(200, handle_list_docs())
            if path == "/jobs":
                return self._send(200, handle_list_jobs())
            if path.startswith("/jobs/"):
                job = handle_get_job(path.rsplit("/", 1)[-1])
                return self._send(200, job) if job else self._send(404, {"detail": "unknown job"})
            return self._serve_static(path)

        def do_POST(self) -> None:
            path = urlparse(self.path).path
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b"{}"
            try:
                payload = json.loads(raw or b"{}")
            except json.JSONDecodeError:
                return self._send(400, {"detail": "body must be JSON"})
            if path == "/jobs":
                return self._send(200, handle_create_job(payload))
            if path == "/admin/reset":
                return self._send(200, handle_reset())
            return self._send(404, {"detail": "not found"})

        def _serve_static(self, path: str) -> None:
            relative = "index.html" if path in ("/", "") else path.lstrip("/").removeprefix("ui/")
            target = (FRONTEND_DIR / relative).resolve()
            if FRONTEND_DIR.resolve() not in target.parents or not target.is_file():
                return self._send(404, {"detail": "not found"})
            types = {".html": "text/html", ".css": "text/css", ".js": "text/javascript", ".svg": "image/svg+xml"}
            self._send(200, target.read_bytes(), types.get(target.suffix, "application/octet-stream"))

    return ThreadingHTTPServer((host, port), Handler)


def main() -> None:
    host = os.environ.get("DOCSCRIBE_HOST", "127.0.0.1")
    port = int(os.environ.get("DOCSCRIBE_PORT", "8000"))
    if settings.enable_worker:
        queue.start()
    if HAS_FASTAPI:
        import uvicorn

        uvicorn.run(app, host=host, port=port, log_level="warning")
        return
    server = _build_stdlib_server(host, port)
    print(f"DocScribe (stdlib server) on http://{host}:{port}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        queue.stop()


if __name__ == "__main__":
    main()

/* Bind job state to the robot's animation.
 *
 * The phase names below are a contract with backend/jobqueue.py:Phase. If a
 * phase is renamed there and not here, the illustration silently stops
 * advancing — so `UNKNOWN_PHASE` logs loudly rather than failing quietly.
 */

const PHASES = ['idle', 'reading', 'thinking', 'writing', 'done', 'failed'];

const PHASE_CAPTIONS = {
  idle: 'waiting',
  reading: 'reading',
  thinking: 'summarizing',
  writing: 'writing',
  done: 'done',
  failed: 'failed',
};

const POLL_INTERVAL_MS = 250;

class RobotView {
  constructor(root) {
    this.stage = root.querySelector('#stage');
    this.caption = root.querySelector('#phase-caption');
    this.detail = root.querySelector('#phase-detail');
    this.progress = root.querySelector('#progress-bar');
    this.bullets = root.querySelector('#bullets');
    this.button = root.querySelector('#run');
    this.picker = root.querySelector('#doc-picker');
    this.note = root.querySelector('#offline-note');
    window.DocScribeRobot.mountRobot(this.stage.querySelector('.robot-slot'));
    this.setPhase('idle', '');
  }

  setPhase(phase, detail) {
    if (!PHASES.includes(phase)) {
      console.warn(`UNKNOWN_PHASE "${phase}" — backend/jobqueue.py:Phase and animate.js have diverged`);
      phase = 'idle';
    }
    this.stage.dataset.phase = phase;
    this.caption.textContent = PHASE_CAPTIONS[phase];
    this.detail.textContent = detail || '';
  }

  setProgress(fraction) {
    this.progress.style.width = `${Math.round((fraction || 0) * 100)}%`;
  }

  setBusy(busy) {
    this.button.disabled = busy;
    this.picker.disabled = busy;
    this.button.textContent = busy ? 'Summarizing…' : 'Summarize';
  }

  showBullets(result) {
    if (!result || !result.bullets || !result.bullets.length) {
      this.bullets.innerHTML = '<p class="empty">No summary yet — pick a document and press Summarize.</p>';
      return;
    }
    const items = result.bullets.map((point) => `<li>${escapeHtml(point)}</li>`).join('');
    const stats = result.stats || {};
    const cached = stats.cache_hit ? ' · served from cache' : '';
    this.bullets.innerHTML =
      `<p><strong>${escapeHtml(result.title || result.doc_id)}</strong>` +
      `<br><span class="empty">${stats.chunks || 0} chunks${cached}</span></p><ul>${items}</ul>`;
  }

  setDocuments(documents) {
    this.picker.innerHTML = documents
      .map((doc) => `<option value="${escapeHtml(doc.doc_id)}">${escapeHtml(doc.title || doc.doc_id)}</option>`)
      .join('');
  }

  setOffline(offline) {
    this.note.textContent = offline
      ? 'Backend not reachable — running the illustration in local demo mode.'
      : '';
  }
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (char) => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]
  ));
}

class Controller {
  constructor(view, client) {
    this.view = view;
    this.client = client;
    this.timer = null;
  }

  async init() {
    await this.client.health();
    this.view.setOffline(this.client.offline);
    this.view.setDocuments(await this.client.listDocuments());
    this.view.showBullets(null);
    this.view.button.addEventListener('click', () => this.run());
  }

  async run() {
    this.stopPolling();
    this.view.setBusy(true);
    this.view.setProgress(0);
    this.view.showBullets(null);
    const { job_id: jobId } = await this.client.createJob(this.view.picker.value);
    this.view.setOffline(this.client.offline);
    this.poll(jobId);
  }

  poll(jobId) {
    this.timer = setInterval(async () => {
      const job = await this.client.getJob(jobId);
      if (!job) return this.finish('failed', 'lost contact with the backend');
      this.view.setPhase(job.phase || 'idle', job.detail);
      this.view.setProgress(job.progress);
      if (job.state === 'succeeded') {
        this.view.showBullets(job.result);
        return this.finish('done', job.detail || 'summary ready');
      }
      if (job.state === 'failed') {
        return this.finish('failed', job.error || 'job failed');
      }
    }, POLL_INTERVAL_MS);
  }

  finish(phase, detail) {
    this.stopPolling();
    this.view.setPhase(phase, detail);
    this.view.setProgress(1);
    this.view.setBusy(false);
  }

  stopPolling() {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
}

document.addEventListener('DOMContentLoaded', async () => {
  const view = new RobotView(document);
  const client = new window.DocScribeAPI.DocScribeClient();
  await new Controller(view, client).init();
});

if (typeof window !== 'undefined') {
  window.DocScribeAnimate = { PHASES, PHASE_CAPTIONS, RobotView, Controller };
}

/* Thin client for the DocScribe backend.
 *
 * Every call degrades to a local demo mode when the backend is unreachable,
 * which is what lets index.html be opened straight off the filesystem: the
 * illustration still walks through all of its phases with nothing running.
 */

const DEFAULT_BASE = (typeof location !== 'undefined' && location.protocol.startsWith('http'))
  ? location.origin
  : 'http://127.0.0.1:8000';

const DEMO_DOCS = [
  { doc_id: 'inference-primer', title: 'A Short Primer on LLM Inference' },
  { doc_id: 'mixture-of-experts', title: 'Mixture of Experts, Briefly' },
  { doc_id: 'caching-strategies', title: 'Caching Strategies for Agent Workloads' },
];

const DEMO_SCRIPT = [
  { phase: 'reading',  progress: 0.15, detail: 'opening document',            hold: 1600 },
  { phase: 'thinking', progress: 0.35, detail: 'splitting document',          hold: 1200 },
  { phase: 'thinking', progress: 0.55, detail: 'summarized chunk 1/3',        hold: 900 },
  { phase: 'thinking', progress: 0.75, detail: 'summarized chunk 3/3',        hold: 900 },
  { phase: 'writing',  progress: 0.95, detail: 'merging summaries',           hold: 1500 },
  { phase: 'done',     progress: 1.0,  detail: 'summary ready',               hold: 0 },
];

class DocScribeClient {
  constructor(baseUrl = DEFAULT_BASE) {
    this.baseUrl = baseUrl.replace(/\/$/, '');
    this.offline = false;
    this._demoJobs = new Map();
  }

  async _fetch(path, options = {}) {
    const response = await fetch(this.baseUrl + path, {
      headers: { 'Content-Type': 'application/json' },
      ...options,
    });
    if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
    return response.json();
  }

  async health() {
    try {
      const result = await this._fetch('/health');
      this.offline = false;
      return result;
    } catch {
      this.offline = true;
      return null;
    }
  }

  async listDocuments() {
    if (this.offline) return DEMO_DOCS;
    try {
      const { documents } = await this._fetch('/docs-list');
      return documents.length ? documents : DEMO_DOCS;
    } catch {
      this.offline = true;
      return DEMO_DOCS;
    }
  }

  async createJob(docId) {
    if (this.offline) return this._startDemoJob(docId);
    try {
      return await this._fetch('/jobs', { method: 'POST', body: JSON.stringify({ doc_id: docId }) });
    } catch {
      this.offline = true;
      return this._startDemoJob(docId);
    }
  }

  async getJob(jobId) {
    if (this._demoJobs.has(jobId)) return this._readDemoJob(jobId);
    try {
      return await this._fetch(`/jobs/${jobId}`);
    } catch {
      this.offline = true;
      return null;
    }
  }

  // ------------------------------------------------------------ demo fallback

  _startDemoJob(docId) {
    const jobId = `demo-${Math.random().toString(36).slice(2, 10)}`;
    this._demoJobs.set(jobId, { docId, startedAt: Date.now() });
    return { job_id: jobId, doc_id: docId, state: 'queued', demo: true };
  }

  _readDemoJob(jobId) {
    const job = this._demoJobs.get(jobId);
    const elapsed = Date.now() - job.startedAt;
    let cursor = 0;
    let step = DEMO_SCRIPT[0];
    for (const candidate of DEMO_SCRIPT) {
      if (elapsed >= cursor) step = candidate;
      cursor += candidate.hold;
    }
    const finished = step.phase === 'done';
    const title = (DEMO_DOCS.find((doc) => doc.doc_id === job.docId) || {}).title || job.docId;
    return {
      job_id: jobId,
      doc_id: job.docId,
      state: finished ? 'succeeded' : 'running',
      phase: step.phase,
      progress: step.progress,
      detail: step.detail,
      demo: true,
      result: finished
        ? {
            title,
            doc_id: job.docId,
            bullets: [
              'Prefill is compute-bound and scales with prompt length; decode is memory-bandwidth-bound and scales with output length.',
              'Running both phases on one device forces a scheduling compromise that suits neither.',
              'A shared prefix can be cached once and reused, collapsing time-to-first-token on later turns.',
            ],
            stats: { chunks: 3, cache_hit: false, reduce_rounds: 1, elapsed_ms: 0 },
          }
        : null,
    };
  }
}

if (typeof window !== 'undefined') {
  window.DocScribeAPI = { DocScribeClient, DEMO_DOCS };
}

/* The robot illustration, as markup.
 *
 * Kept in JavaScript rather than a standalone .svg file for one practical
 * reason: a browser opened on file:// refuses to fetch a sibling SVG, but it
 * will happily run a sibling script. So index.html works with no server.
 *
 * Geometry lives here; every colour and stroke width lives in style.css.
 */

/** Build a gear outline centred on (cx, cy).
 *
 * Each tooth contributes four vertices — rise, flat top, flat top, fall — so
 * the result reads as a cog rather than a star. `outer` is the tip radius,
 * `inner` the root radius.
 */
function gearPath(cx, cy, outer, inner, teeth) {
  const points = [];
  const pitch = (Math.PI * 2) / teeth;
  const half = pitch * 0.22;
  const at = (radius, angle) =>
    `${(cx + radius * Math.cos(angle)).toFixed(2)} ${(cy + radius * Math.sin(angle)).toFixed(2)}`;
  for (let i = 0; i < teeth; i += 1) {
    const centre = i * pitch - Math.PI / 2;
    points.push(at(inner, centre - half * 1.8));
    points.push(at(outer, centre - half));
    points.push(at(outer, centre + half));
    points.push(at(inner, centre + half * 1.8));
  }
  return `M${points.join(' L')} Z`;
}

/** Evenly spaced horizontal rules, used for text on a book page. */
function pageRules(x1, x2, yStart, count, slope) {
  return Array.from({ length: count }, (_, i) => {
    const y = yStart + i * 9;
    return `<line class="page-rule" x1="${x1}" y1="${y + i * slope}" x2="${x2}" y2="${y + i * slope - slope * 2}" />`;
  }).join('\n      ');
}

