/** Inject the illustration into `target`. */
function mountRobot(target) {
  const node = typeof target === 'string' ? document.querySelector(target) : target;
  if (!node) throw new Error('mountRobot: target not found');
  node.innerHTML = ROBOT_SVG;
  return node.querySelector('svg');
}

if (typeof window !== 'undefined') {
  window.DocScribeRobot = { ROBOT_SVG, mountRobot, gearPath };
}

/* DocScribe — visual theme.
 *
 * Everything the robot looks like is driven by the custom properties below.
 * Change a value here and the whole illustration follows; nothing downstream
 * hardcodes a colour.
 */

:root {
  /* ---- Robot palette --------------------------------------------------- */
  --robot-fill:      #7EC8E3;   /* light blue */
  --robot-fill-dark: #5AAFCC;   /* shaded panels */
  --robot-stroke:    #000000;   /* black borders */
  --stroke-width:    3px;
  --stroke-width-thin: 2px;

  /* ---- Props ----------------------------------------------------------- */
  --book-fill:       #FFFFFF;
  --book-spine:      #7EC8E3;
  --page-line:       #C9D6DD;
  --screen-fill:     #12181D;
  --screen-text:     #7EC8E3;
  --gear-fill:       #FFFFFF;
  --eye-fill:        #000000;
  --accent:          #7EC8E3;

  /* ---- Page ------------------------------------------------------------ */
  --bg:              #F4F8FA;
  --surface:         #FFFFFF;
  --ink:             #0E1417;
  --ink-muted:       #59696F;
  --border:          #000000;
  --radius:          14px;

  /* ---- Motion ---------------------------------------------------------- */
  --beat:            1.4s;
  --ease:            cubic-bezier(0.45, 0.05, 0.35, 1);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  padding: 32px 20px 56px;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 ui-sans-serif, -apple-system, "Segoe UI", Roboto, sans-serif;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

header { text-align: center; max-width: 620px; }
header h1 { margin: 0 0 6px; font-size: 30px; letter-spacing: -0.02em; }
header p { margin: 0; color: var(--ink-muted); }

/* ------------------------------------------------------------------ stage */

.stage {
  width: min(560px, 100%);
  background: var(--surface);
  border: var(--stroke-width) solid var(--border);
  border-radius: var(--radius);
  padding: 20px 20px 12px;
  box-shadow: 6px 6px 0 var(--border);
}

.stage svg { display: block; width: 100%; height: auto; }

.phase-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 10px;
  padding-top: 10px;
  border-top: var(--stroke-width-thin) solid var(--border);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.phase-label .detail {
  text-transform: none;
  letter-spacing: 0;
  color: var(--ink-muted);
  font-size: 13px;
  text-align: right;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.progress {
  width: min(560px, 100%);
  height: 14px;
  background: var(--surface);
  border: var(--stroke-width-thin) solid var(--border);
  border-radius: 999px;
  overflow: hidden;
}
.progress > span {
  display: block;
  height: 100%;
  width: 0%;
  background: var(--accent);
  transition: width 0.35s var(--ease);
}

/* ----------------------------------------------------------------- robot */

.robot-part {
  fill: var(--robot-fill);
  stroke: var(--robot-stroke);
  stroke-width: var(--stroke-width);
  stroke-linejoin: round;
}
.robot-part.shaded { fill: var(--robot-fill-dark); }
.eye { fill: var(--eye-fill); stroke: none; }
.book-page { fill: var(--book-fill); stroke: var(--robot-stroke); stroke-width: var(--stroke-width); }
.book-spine { fill: var(--book-spine); stroke: var(--robot-stroke); stroke-width: var(--stroke-width); }
.page-rule { stroke: var(--page-line); stroke-width: var(--stroke-width-thin); stroke-linecap: round; }
.screen { fill: var(--screen-fill); stroke: var(--robot-stroke); stroke-width: var(--stroke-width); }
.screen-line { stroke: var(--screen-text); stroke-width: var(--stroke-width-thin); stroke-linecap: round; }
.gear { fill: var(--gear-fill); stroke: var(--robot-stroke); stroke-width: var(--stroke-width-thin); }
.bubble { fill: var(--surface); stroke: var(--robot-stroke); stroke-width: var(--stroke-width); }
.desk { stroke: var(--robot-stroke); stroke-width: var(--stroke-width); stroke-linecap: round; }

/* Props are hidden by default and revealed per phase. */
#book, #thought, #workstation { opacity: 0; transition: opacity 0.3s var(--ease); }
[data-phase="reading"] #book,
[data-phase="thinking"] #book,
[data-phase="thinking"] #thought,
[data-phase="writing"] #workstation,
[data-phase="done"] #workstation { opacity: 1; }

/* ------------------------------------------------------------- animations */

@keyframes blink      { 0%, 92%, 100% { transform: scaleY(1); } 96% { transform: scaleY(0.1); } }
@keyframes antenna    { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-3px); } }
@keyframes page-turn  { 0%, 100% { transform: rotateY(0deg); } 50% { transform: rotateY(-38deg); } }
@keyframes scan       { 0% { transform: translateX(0); } 100% { transform: translateX(26px); } }
@keyframes spin       { to { transform: rotate(360deg); } }
@keyframes spin-back  { to { transform: rotate(-360deg); } }
@keyframes bob        { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(3px); } }
@keyframes type-flash { 0%, 100% { opacity: 0.25; } 50% { opacity: 1; } }
@keyframes nod        { 0%, 100% { transform: rotate(0deg); } 50% { transform: rotate(4deg); } }

#eyes { animation: blink 4s infinite steps(1, end); transform-origin: 200px 130px; }
#antenna-tip { animation: antenna var(--beat) ease-in-out infinite; transform-origin: center; }

[data-phase="reading"] #page-right { animation: page-turn 2.2s var(--ease) infinite; transform-origin: 200px 248px; }
[data-phase="reading"] #scan-dot { animation: scan 1.1s var(--ease) infinite alternate; }
[data-phase="reading"] #head { animation: nod 3s ease-in-out infinite; transform-origin: 200px 180px; }

[data-phase="thinking"] #gear-big { animation: spin 3s linear infinite; transform-origin: 310px 64px; }
[data-phase="thinking"] #gear-small { animation: spin-back 2s linear infinite; transform-origin: 346px 92px; }

[data-phase="writing"] #arm-left { animation: bob 0.42s ease-in-out infinite; transform-origin: 129px 205px; }
[data-phase="writing"] #arm-right { animation: bob 0.42s ease-in-out infinite reverse; transform-origin: 271px 205px; }
[data-phase="writing"] .screen-line { animation: type-flash 0.9s ease-in-out infinite; }
[data-phase="writing"] .screen-line:nth-of-type(2) { animation-delay: 0.15s; }
[data-phase="writing"] .screen-line:nth-of-type(3) { animation-delay: 0.3s; }
[data-phase="writing"] .screen-line:nth-of-type(4) { animation-delay: 0.45s; }

[data-phase="done"] #eyes { animation: none; }
[data-phase="failed"] .robot-part { fill: #E9EDEF; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

/* ------------------------------------------------------------------ panel */

.panel {
  width: min(560px, 100%);
  background: var(--surface);
  border: var(--stroke-width) solid var(--border);
  border-radius: var(--radius);
  padding: 18px 20px;
  box-shadow: 6px 6px 0 var(--border);
}
.panel h2 { margin: 0 0 10px; font-size: 15px; text-transform: uppercase; letter-spacing: 0.1em; }
.panel ul { margin: 0; padding-left: 20px; }
.panel li { margin-bottom: 8px; }
.panel .empty { color: var(--ink-muted); font-style: italic; }

.controls { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; justify-content: center; }

select, button {
  font: inherit;
  padding: 9px 14px;
  border: var(--stroke-width-thin) solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  color: var(--ink);
  cursor: pointer;
}
button { background: var(--accent); font-weight: 600; box-shadow: 3px 3px 0 var(--border); }
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--border); }
button[disabled] { opacity: 0.5; cursor: not-allowed; box-shadow: none; transform: none; }

.offline-note {
  width: min(560px, 100%);
  font-size: 13px;
  color: var(--ink-muted);
  text-align: center;
}
